CREATE ROLE forge_owner LOGIN PASSWORD 'forge_owner_lab_password';
CREATE ROLE forge_app LOGIN PASSWORD 'forge_app_lab_password';
CREATE SCHEMA forge AUTHORIZATION forge_owner;
ALTER DATABASE forgetrack SET search_path TO forge, public;
SET ROLE forge_owner;
SET search_path TO forge, public;
CREATE TABLE users (id SERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, role_name TEXT NOT NULL, user_type TEXT NOT NULL CHECK (user_type IN ('crew','racer')), password_hash TEXT NOT NULL, driver_id INT, active BOOLEAN DEFAULT true);
CREATE TABLE drivers (id SERIAL PRIMARY KEY, display_name TEXT NOT NULL, nationality TEXT NOT NULL, competition_class TEXT NOT NULL, race_starts INT NOT NULL DEFAULT 0, podiums INT NOT NULL DEFAULT 0, wins INT NOT NULL DEFAULT 0, best_lap_ms INT);
ALTER TABLE users ADD CONSTRAINT users_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES drivers(id);
CREATE TABLE cars (id SERIAL PRIMARY KEY, car_code TEXT UNIQUE NOT NULL, model TEXT NOT NULL, manufacturer TEXT NOT NULL, model_year INT NOT NULL, powertrain TEXT NOT NULL, image_url TEXT NOT NULL, power_hp INT NOT NULL DEFAULT 500, weight_kg INT NOT NULL DEFAULT 1300, top_speed_kph INT NOT NULL DEFAULT 280, total_km INT NOT NULL DEFAULT 0, primary_driver_id INT REFERENCES drivers(id), status TEXT NOT NULL);
CREATE TABLE modifications (id SERIAL PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE builds (id SERIAL PRIMARY KEY, build_code TEXT UNIQUE NOT NULL, car_id INT NOT NULL REFERENCES cars(id), name TEXT NOT NULL, status TEXT NOT NULL, restricted BOOLEAN DEFAULT false, notes TEXT);
CREATE TABLE build_modifications (build_id INT REFERENCES builds(id) ON DELETE CASCADE, modification_id INT REFERENCES modifications(id), PRIMARY KEY(build_id, modification_id));
CREATE TABLE race_events (id SERIAL PRIMARY KEY, name TEXT NOT NULL, circuit TEXT NOT NULL, event_date DATE NOT NULL, status TEXT NOT NULL, laps INT NOT NULL DEFAULT 0, distance_km NUMERIC(6,2) NOT NULL DEFAULT 0, lap_record TEXT, weather_note TEXT);
CREATE TABLE race_entries (id SERIAL PRIMARY KEY, event_id INT REFERENCES race_events(id), driver_id INT REFERENCES drivers(id), car_id INT REFERENCES cars(id), grid_position INT);
CREATE TABLE telemetry (id SERIAL PRIMARY KEY, session_code TEXT UNIQUE NOT NULL, car_code TEXT NOT NULL, circuit TEXT NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), payload JSONB DEFAULT '{}'::jsonb);
CREATE TABLE workshop_jobs (id SERIAL PRIMARY KEY, job_code TEXT UNIQUE NOT NULL, car_id INT REFERENCES cars(id), status TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE audit_logs (id SERIAL PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE team_messages (id SERIAL PRIMARY KEY, author_id INT NOT NULL REFERENCES users(id), body TEXT NOT NULL CHECK (char_length(body) BETWEEN 1 AND 500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE flags (id SERIAL PRIMARY KEY, challenge TEXT UNIQUE NOT NULL, flag_value TEXT NOT NULL);
REVOKE ALL ON SCHEMA forge FROM PUBLIC;
GRANT USAGE ON SCHEMA forge TO forge_app;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA forge TO forge_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA forge TO forge_app;
ALTER DEFAULT PRIVILEGES FOR ROLE forge_owner IN SCHEMA forge GRANT SELECT, INSERT, UPDATE ON TABLES TO forge_app;
ALTER DEFAULT PRIVILEGES FOR ROLE forge_owner IN SCHEMA forge GRANT USAGE, SELECT ON SEQUENCES TO forge_app;
RESET ROLE;
